const $=id=>document.getElementById(id);
async function api(url,opts={}){const headers=new Headers(opts.headers||{});const token=localStorage.getItem('agriCareToken');if(token)headers.set('Authorization','Bearer '+token);const r=await fetch(url,{...opts,headers});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.detail||d.message||`Request failed (${r.status})`);return d}
function show(id,html){$(id).innerHTML=`<div class="resultbox">${html}</div>`}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
document.querySelectorAll('.nav').forEach(b=>b.addEventListener('click',()=>go(b.dataset.page)));
document.querySelectorAll('[data-go]').forEach(c=>c.addEventListener('click',()=>go(c.dataset.go)));
function go(page){document.querySelectorAll('.page').forEach(p=>p.classList.toggle('show',p.id===page));document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.page===page));window.scrollTo({top:0,behavior:'smooth'})}
async function fertilizer(){try{let d=await api('/api/fertilizer/recommend',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({crop:$('crop').value,soil_type:$('soil').value,nitrogen:+$('n').value,phosphorus:+$('p').value,potassium:+$('k').value,ph:+$('ph').value})});show('fertResult',`<h3>Soil screening · ${esc(d.crop)}</h3><p><span class="pill">${esc(d.assessment)}</span></p><b>Low readings:</b> ${d.low_nutrients.length?d.low_nutrients.map(esc).join(', '):'None flagged by screening'}<ul>${d.recommendations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><b>Next step:</b> ${esc(d.next_step)}<p class="notice">${esc(d.disclaimer)}</p>`)}catch(e){show('fertResult',esc(e.message))}}
async function detectPest(){let f=$('pestFile').files[0];if(!f){show('pestResult','Please select an image first.');return}let fd=new FormData();fd.append('image',f);show('pestResult','Image analysis is running…');try{let d=await api('/api/pest/detect',{method:'POST',body:fd});show('pestResult',`<h3>${esc(d.plant||'Plant not identified')}</h3><p>Plant confidence: ${d.plant_confidence_percent??'—'}%</p><ul>${(d.diseases||[]).map(x=>`<li>${esc(x.name)} — ${x.confidence_percent}%</li>`).join('')}</ul><p class="notice">${esc(d.notice||d.message||'')}</p>`)}catch(e){show('pestResult',esc(e.message))}}
$('pestFile').addEventListener('change',e=>{let f=e.target.files[0];if(f){$('pestPreview').innerHTML=`<img src="${URL.createObjectURL(f)}" alt="Selected crop image">`}})
async function simulate(){try{let d=await api('/api/digital-twin/simulate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({crop:$('tCrop').value,area_acres:+$('area').value,soil_moisture:+$('moist').value,temperature_c:+$('temp').value,irrigation_percent:+$('irr').value,days:+$('days').value})});show('twinResult',`<h3>Scenario result · ${esc(d.crop)}</h3><p>Estimated moisture after ${d.simulation_days} days: <b>${d.estimated_moisture_after_simulation}%</b></p><p>Scenario risk: <span class="pill">${esc(d.scenario_risk)}</span></p><p>Heat stress indicator: ${esc(d.heat_stress_indicator)}</p><p>${esc(d.notice)}</p>`)}catch(e){show('twinResult',esc(e.message))}}
let assistantConversationId=localStorage.getItem('agriCareConversation')||((crypto.randomUUID&&crypto.randomUUID())||('conv-'+Date.now()));
localStorage.setItem('agriCareConversation',assistantConversationId);
function updateAssistantWelcome(){const lang=$('assistantLang').value;const welcome={English:'Hello! I can help with crop growing, soil, irrigation, pests, diseases and Indian farming practices. Ask a question or use a voice prompt.',Hindi:'नमस्ते! मैं फसल उगाने, मिट्टी, सिंचाई, कीट, रोग और भारतीय खेती के तरीकों में मदद कर सकता हूँ। अपना सवाल पूछें या आवाज़ से बताएं।',Telugu:'నమస్కారం! పంటల సాగు, నేల, నీటిపారుదల, పురుగులు, వ్యాధులు మరియు భారతీయ వ్యవసాయ పద్ధతులపై సహాయం చేస్తాను. మీ ప్రశ్న అడగండి లేదా వాయిస్ ఉపయోగించండి.'};const first=$('assistantChat').querySelector('.chat-message.bot');if(first&&$('assistantChat').children.length===1)first.textContent=welcome[lang];}
$('assistantLang').addEventListener('change',updateAssistantWelcome);
function appendChat(text,role){const box=$('assistantChat');const el=document.createElement('div');el.className='chat-message '+role;el.textContent=text;box.appendChild(el);box.scrollTop=box.scrollHeight;}
async function askAssistant(){const lang=$('assistantLang').value,q=$('assistantQuestion').value.trim();if(!q)return;appendChat(q,'user');$('assistantQuestion').value='';$('assistantStatus').textContent='Farmer Assistant is preparing a response…';
 try{const d=await api('/api/assistant',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:q,language:lang,conversation_id:assistantConversationId,context:{farm_details:$('assistantContext').value,crop:$('assistantCrop').value,state:$('assistantState').value,district:$('assistantDistrict').value,latitude:$('assistantLat').value?Number($('assistantLat').value):undefined,longitude:$('assistantLon').value?Number($('assistantLon').value):undefined}})});appendChat(d.answer,'bot');$('assistantStatus').textContent=d.provider||'Response ready';speak(d.answer,lang);}
 catch(e){appendChat(e.message,'system');$('assistantStatus').textContent='Unable to reach the assistant. Please retry.'}}
function setAssistantPrompt(topic){const prompts={weather:{English:'What weather information should I consider for my farm?',Hindi:'मेरे खेत के लिए मौसम की किन बातों पर ध्यान देना चाहिए?',Telugu:'నా పొలానికి వాతావరణంలో ఏ విషయాలు గమనించాలి?'},crop:{English:'Which crops suit my farm and current season?',Hindi:'मेरे खेत और वर्तमान मौसम के लिए कौन सी फसलें उपयुक्त हैं?',Telugu:'నా పొలం మరియు ప్రస్తుత సీజన్‌కు ఏ పంటలు అనుకూలం?'},market:{English:'How can I check historical mandi prices for my crop?',Hindi:'मैं अपनी फसल के ऐतिहासिक मंडी भाव कैसे देख सकता हूँ?',Telugu:'నా పంటకు సంబంధించిన చారిత్రక మండీ ధరలను ఎలా చూడాలి?'},disease:{English:'Help me assess these crop disease symptoms.',Hindi:'मेरी फसल के इन रोग लक्षणों को समझने में मदद करें।',Telugu:'నా పంటలో కనిపిస్తున్న ఈ వ్యాధి లక్షణాలను అర్థం చేసుకోవడంలో సహాయం చేయండి.'},soil:{English:'How should I manage soil health and nutrients?',Hindi:'मिट्टी की सेहत और पोषक तत्वों का प्रबंधन कैसे करूँ?',Telugu:'నేల ఆరోగ్యం మరియు పోషకాలను ఎలా నిర్వహించాలి?'}};$('assistantQuestion').value=prompts[topic][$('assistantLang').value]||prompts[topic].English;$('assistantQuestion').focus();}
function clearAssistantChat(){assistantConversationId=(crypto.randomUUID&&crypto.randomUUID())||('conv-'+Date.now());localStorage.setItem('agriCareConversation',assistantConversationId);$('assistantChat').innerHTML='<div class="chat-message bot">New conversation started. Ask your farming question.</div>';$('assistantStatus').textContent='';}
function startAssistantSpeech(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){$('assistantStatus').textContent='Speech recognition is not supported in this browser. Type your question instead.';return}const r=new SR(),lang=$('assistantLang').value;r.lang=lang==='Telugu'?'te-IN':lang==='Hindi'?'hi-IN':'en-IN';r.onresult=e=>{$('assistantQuestion').value=e.results[0][0].transcript};r.onerror=()=>{$('assistantStatus').textContent='Voice input could not be captured.'};r.start();}
function speak(text,lang){if(!('speechSynthesis'in window))return;const u=new SpeechSynthesisUtterance(text);u.lang=lang==='Telugu'?'te-IN':lang==='Hindi'?'hi-IN':'en-IN';speechSynthesis.cancel();speechSynthesis.speak(u)}
async function disease(){const body={crop:$('diseaseCrop').value,state:$('diseaseState').value,district:$('diseaseDistrict').value,growth_stage:$('diseaseStage').value,plant_age:$('diseaseAge').value,soil_type:$('diseaseSoil').value,weather_conditions:$('diseaseWeather').value,symptoms:$('diseaseSymptoms').value,affected_parts:$('diseaseParts').value,symptom_duration:$('diseaseDuration').value};$('diseaseResult').innerHTML='<p class="empty-note">Preparing crop health guidance…</p>';
 try{const d=await api('/api/disease/guidance',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const sections=[['Common diseases',d.common_diseases],['Early warning signs',d.early_warning_signs],['Possible causes',d.possible_causes],['Weather risk factors',d.weather_risk_factors],['Prevention',d.prevention],['Crop management',d.crop_management],['Organic and biological options',d.organic_biological_options],['Integrated pest and disease management',d.ipdm],['Treatment safety',d.treatment_safety],['Irrigation management',d.irrigation],['Soil health',d.soil_health],['Crop-growing guidance',Object.entries(d.crop_growing_guidance).map(([k,v])=>k.replaceAll('_',' ')+': '+v)],['When to contact a KVK', [d.when_to_contact_kvk]]];$('diseaseResult').innerHTML=`<h2>${esc(d.crop)} · ${esc(d.location||'Location not specified')}</h2><p class="notice">General agricultural guidance only — not a confirmed diagnosis or verified district-specific prescription.</p>`+sections.map(([title,items])=>`<div class="guidance-section"><h3>${esc(title)}</h3>${Array.isArray(items)?'<ul>'+items.map(x=>`<li>${esc(x)}</li>`).join('')+'</ul>':'<p>'+esc(items)+'</p>'}</div>`).join('')+`<p class="muted">${esc(d.verification)}</p>`;}
 catch(e){$('diseaseResult').textContent=e.message}}
async function scanDiseaseImage(){const f=$('diseaseImage').files[0];if(!f){$('diseaseImageResult').textContent='Select a crop image first.';return}const fd=new FormData();fd.append('image',f);$('diseaseImageResult').textContent='Sending image to the configured image-analysis provider…';try{const d=await api('/api/pest/detect',{method:'POST',body:fd});$('diseaseImageResult').innerHTML=`<h3>${esc(d.plant||'Plant not identified')}</h3><p>Plant confidence: ${d.plant_confidence_percent??'—'}%</p><ul>${(d.diseases||[]).map(x=>`<li>${esc(x.name)} — ${x.confidence_percent}%</li>`).join('')}</ul><p class="notice">${esc(d.notice||d.message||'')}</p>`}catch(e){$('diseaseImageResult').textContent=e.message}}
async function irrigation(){try{let d=await api('/api/irrigation/advice?moisture='+encodeURIComponent($('irrigMoist').value));show('irrigResult',`<h3>Moisture: ${d.soil_moisture_percent}%</h3><p>${esc(d.advice)}</p>`)}catch(e){show('irrigResult',esc(e.message))}}

// Indian agricultural analytics: all financial values originate from saved farm records.
const inr = value => new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(Number(value||0));
const queryFilters = () => {
  const p=new URLSearchParams();let start=$('aStart')?.value||'',end=$('aEnd')?.value||'';
  const month=$('aMonth')?.value||'',fy=$('aYearFilter')?.value||'';
  if(month){const [yy,mm]=month.split('-').map(Number);start=`${yy}-${String(mm).padStart(2,'0')}-01`;end=`${yy}-${String(mm).padStart(2,'0')}-${String(new Date(yy,mm,0).getDate()).padStart(2,'0')}`}
  else if(fy&&!start&&!end){start=`${fy}-04-01`;end=`${Number(fy)+1}-03-31`}
  if(start)p.set('start_date',start);if(end)p.set('end_date',end);
  [['crop','aCropFilter'],['state','aStateFilter'],['district','aDistrictFilter'],['season','aSeasonFilter']].forEach(([k,id])=>{const v=$(id)?.value?.trim();if(v)p.set(k,v)});
  return p.toString();
};
function resetAnalyticsFilters(){['aMonth','aStart','aEnd','aCropFilter','aStateFilter','aDistrictFilter','aSeasonFilter','aYearFilter'].forEach(id=>{if($(id))$(id).value=''});loadAnalytics();}
function validDateRange(fromId,toId){const from=$(fromId)?.value||'',to=$(toId)?.value||'';if(from&&to&&from>to){return false}return true;}
const chartPalette={revenue:'#39875b',expenses:'#d7a34a',profit:'#477fbd',grid:'#e7eee8',text:'#718278'};

// Frontend-only sample values for charts. These never enter the farmer database.
const AGRICARE_SAMPLE_ANALYTICS={
 crops:[{crop:'Rice',production:6200,share:32},{crop:'Maize',production:4600,share:24},{crop:'Cotton',production:5100,share:26},{crop:'Tomato',production:3400,share:18}],
 income:[{month:'Jun',amount:42000},{month:'Jul',amount:51000},{month:'Aug',amount:47500},{month:'Sep',amount:59000},{month:'Oct',amount:68000},{month:'Nov',amount:73500}]
};
function renderSampleAnalyticsPreview(){
 const bar=$('sampleCropBar'),pie=$('sampleCropPie'),line=$('sampleIncomeLine');if(!bar||!pie||!line)return;
 const palette=['#39875b','#d7a34a','#6e9eaf','#b87955'];
 {const {ctx,w,h}=chartCanvasSize(bar,230),rows=AGRICARE_SAMPLE_ANALYTICS.crops,left=42,right=12,top=16,bottom=38,pw=w-left-right,ph=h-top-bottom,max=Math.max(...rows.map(x=>x.production))*1.15;ctx.strokeStyle='#e7eee8';ctx.fillStyle='#718278';ctx.font='10px Arial';ctx.textAlign='right';for(let i=0;i<=4;i++){const v=max*i/4,y=top+ph-(v/max)*ph;ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(w-right,y);ctx.stroke();ctx.fillText(Math.round(v).toLocaleString('en-IN'),left-6,y)}const slot=pw/rows.length,bw=Math.min(42,slot*.58);rows.forEach((r,i)=>{const bh=r.production/max*ph,x=left+i*slot+(slot-bw)/2,y=top+ph-bh;ctx.fillStyle=palette[i%palette.length];ctx.fillRect(x,y,bw,bh);ctx.fillStyle='#61766a';ctx.textAlign='center';ctx.fillText(r.crop,x+bw/2,h-17);});}
 {const {ctx,w,h}=chartCanvasSize(pie,230),rows=AGRICARE_SAMPLE_ANALYTICS.crops,cx=w/2,cy=105,r=Math.min(76,w*.25),total=rows.reduce((a,x)=>a+x.share,0);let a=-Math.PI/2;rows.forEach((item,i)=>{const next=a+item.share/total*Math.PI*2;ctx.beginPath();ctx.moveTo(cx,cy);ctx.arc(cx,cy,r,a,next);ctx.closePath();ctx.fillStyle=palette[i%palette.length];ctx.fill();a=next});ctx.font='10px Arial';ctx.textAlign='left';rows.forEach((item,i)=>{const y=190+i*10;ctx.fillStyle=palette[i%palette.length];ctx.fillRect(w/2-92,y-7,7,7);ctx.fillStyle='#61766a';ctx.fillText(`${item.crop} ${item.share}%`,w/2-80,y);});}
 {const {ctx,w,h}=chartCanvasSize(line,230),rows=AGRICARE_SAMPLE_ANALYTICS.income,left=42,right=12,top=18,bottom=35,pw=w-left-right,ph=h-top-bottom,max=Math.max(...rows.map(x=>x.amount))*1.15;ctx.strokeStyle='#e7eee8';ctx.fillStyle='#718278';ctx.font='10px Arial';ctx.textAlign='right';for(let i=0;i<=4;i++){const v=max*i/4,y=top+ph-(v/max)*ph;ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(w-right,y);ctx.stroke();ctx.fillText('₹'+Math.round(v/1000)+'k',left-6,y)}ctx.beginPath();rows.forEach((r,i)=>{const x=left+i*pw/(rows.length-1),y=top+ph-r.amount/max*ph;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.strokeStyle='#39875b';ctx.lineWidth=2.5;ctx.stroke();rows.forEach((r,i)=>{const x=left+i*pw/(rows.length-1),y=top+ph-r.amount/max*ph;ctx.beginPath();ctx.arc(x,y,3.5,0,Math.PI*2);ctx.fillStyle='#39875b';ctx.fill();ctx.fillStyle='#61766a';ctx.textAlign='center';ctx.fillText(r.month,x,h-12)});}
}

function chartCanvasSize(canvas,height){const w=Math.max(320,canvas.clientWidth||600),h=height,dpr=window.devicePixelRatio||1;canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);canvas.style.height=h+'px';const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);return {ctx,w,h};}
function chartTooltip(id,canvas,x,y,html){const tip=$(id);if(!tip)return;tip.innerHTML=html;tip.style.display='block';const wrap=canvas.parentElement;const maxX=Math.max(8,wrap.clientWidth-tip.offsetWidth-8),maxY=Math.max(8,wrap.clientHeight-tip.offsetHeight-8);tip.style.left=Math.max(8,Math.min(x+12,maxX))+'px';tip.style.top=Math.max(8,Math.min(y+10,maxY))+'px';}
function hideChartTooltip(id){if($(id))$(id).style.display='none';}
function renderMonthlyChart(items){
 const canvas=$('monthlyChart'),empty=$('monthlyEmpty');if(!canvas)return;
 if(!items?.length){canvas.style.display='none';empty.style.display='block';hideChartTooltip('monthlyTooltip');return}
 canvas.style.display='block';empty.style.display='none';const {ctx,w,h}=chartCanvasSize(canvas,250);
 const left=52,right=16,top=18,bottom=48,pw=w-left-right,ph=h-top-bottom;
 const values=items.flatMap(x=>[Number(x.revenue_inr||0),Number(x.expenses_inr||0),Number(x.profit_inr||0)]),min=Math.min(0,...values),max=Math.max(1,...values),range=max-min||1;
 const y=v=>top+(max-v)/range*ph,step=pw/Math.max(1,items.length-1);
 ctx.font='10px Arial';ctx.textAlign='right';ctx.textBaseline='middle';ctx.strokeStyle=chartPalette.grid;ctx.fillStyle=chartPalette.text;
 for(let i=0;i<=4;i++){const v=max-(range*i/4),yy=y(v);ctx.beginPath();ctx.moveTo(left,yy);ctx.lineTo(w-right,yy);ctx.stroke();ctx.fillText(inr(v).replace('₹','₹'),left-7,yy)}
 const series=[['revenue_inr',chartPalette.revenue],['expenses_inr',chartPalette.expenses],['profit_inr',chartPalette.profit]];
 const points=[];series.forEach(([key,color])=>{ctx.beginPath();ctx.strokeStyle=color;ctx.lineWidth=2.5;items.forEach((item,i)=>{const pt={x:left+(items.length===1?pw/2:i*step),y:y(Number(item[key]||0))};(points[i]??=[]).push({key,color,...pt});if(i===0)ctx.moveTo(pt.x,pt.y);else ctx.lineTo(pt.x,pt.y)});ctx.stroke();items.forEach((item,i)=>{const pt=points[i][series.findIndex(a=>a[0]===key)];ctx.beginPath();ctx.arc(pt.x,pt.y,3.5,0,Math.PI*2);ctx.fillStyle=color;ctx.fill()})});
 ctx.textAlign='center';ctx.textBaseline='top';ctx.fillStyle=chartPalette.text;items.forEach((item,i)=>ctx.fillText(String(item.month).slice(5),left+(items.length===1?pw/2:i*step),h-bottom+10));
 const legends=[['Revenue',chartPalette.revenue],['Expenses',chartPalette.expenses],['Net profit',chartPalette.profit]];let lx=left;ctx.font='10px Arial';legends.forEach(([label,color])=>{ctx.fillStyle=color;ctx.fillRect(lx,h-13,9,9);ctx.fillStyle=chartPalette.text;ctx.textAlign='left';ctx.fillText(label,lx+13,h-13);lx+=label.length*6+34});
 const nearest=e=>{const r=canvas.getBoundingClientRect(),mx=e.clientX-r.left,my=e.clientY-r.top;let idx=Math.round((mx-left)/(items.length===1?pw:step));if(idx<0||idx>=items.length||Math.abs(mx-(left+(items.length===1?pw/2:idx*step)))>Math.max(18,step/2))return null;return {idx,mx,my}};
 canvas.onmousemove=e=>{const hit=nearest(e);if(!hit){hideChartTooltip('monthlyTooltip');return}const m=items[hit.idx];chartTooltip('monthlyTooltip',canvas,hit.mx,hit.my,`<b>${esc(m.month)}</b><br>Revenue: ${inr(m.revenue_inr)}<br>Expenses: ${inr(m.expenses_inr)}<br>Net profit: ${inr(m.profit_inr)}`)};
 canvas.onmouseleave=()=>hideChartTooltip('monthlyTooltip');canvas.onclick=e=>{const hit=nearest(e);if(!hit)return;const [yy,mm]=String(items[hit.idx].month).split('-').map(Number),last=new Date(yy,mm,0).getDate();$('aStart').value=`${yy}-${String(mm).padStart(2,'0')}-01`;$('aEnd').value=`${yy}-${String(mm).padStart(2,'0')}-${last}`;loadAnalytics()};
}
function renderBarList(id,items,labelKey,valueKey){
  const root=$(id);if(!items?.length){root.innerHTML='<p class="empty-note">No saved records available for this view.</p>';return}
  const max=Math.max(1,...items.map(x=>Number(x[valueKey]||0)));
  root.innerHTML=items.map(x=>`<div class="bar-row" tabindex="0" role="button" title="Click to filter by ${esc(x[labelKey])}"><span>${esc(x[labelKey])}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.max(0,Number(x[valueKey]||0)/max*100)}%"></div></div><span class="bar-value">${inr(x[valueKey])}</span></div>`).join('');
  root.querySelectorAll('.bar-row').forEach((row,i)=>row.addEventListener('click',()=>{const value=items[i][labelKey];if(labelKey==='crop'&&$('aCropFilter')){$('aCropFilter').value=value;loadAnalytics()}else if(labelKey==='season'&&$('aSeasonFilter')){$('aSeasonFilter').value=value;loadAnalytics()}else if(labelKey==='state'&&$('hmState')){$('hmState').value=value;loadHistoricalMarket()}else if(labelKey==='market'&&$('hmMarket')){$('hmMarket').value=value;loadHistoricalMarket()}}));
}
function renderCropPerformanceChart(items){
 const canvas=$('cropPerformanceChart'),empty=$('cropPerformanceEmpty');if(!canvas)return;
 const rows=(items||[]).filter(x=>Number(x.revenue_inr||0)!==0||Number(x.expenses_inr||0)!==0||Number(x.profit_inr||0)!==0);
 if(!rows.length){canvas.style.display='none';empty.style.display='block';hideChartTooltip('cropPerformanceTooltip');return}
 canvas.style.display='block';empty.style.display='none';const {ctx,w,h}=chartCanvasSize(canvas,290),left=48,right=12,top=18,bottom=58,pw=w-left-right,ph=h-top-bottom;
 const vals=rows.flatMap(x=>[Number(x.revenue_inr||0),Number(x.expenses_inr||0),Number(x.profit_inr||0)]),min=Math.min(0,...vals),max=Math.max(1,...vals),range=max-min||1,y=v=>top+(max-v)/range*ph,zero=y(0),group=pw/rows.length,bw=Math.max(5,Math.min(22,group*.19));
 ctx.font='10px Arial';ctx.textAlign='right';ctx.textBaseline='middle';ctx.fillStyle=chartPalette.text;ctx.strokeStyle=chartPalette.grid;
 for(let i=0;i<=4;i++){const v=max-range*i/4,yy=y(v);ctx.beginPath();ctx.moveTo(left,yy);ctx.lineTo(w-right,yy);ctx.stroke();ctx.fillText(inr(v),left-6,yy)}
 const defs=[['revenue_inr','Revenue',chartPalette.revenue],['expenses_inr','Expenses',chartPalette.expenses],['profit_inr','Net profit',chartPalette.profit]],hits=[];
 rows.forEach((row,i)=>{const center=left+group*(i+.5);defs.forEach((d,j)=>{const val=Number(row[d[0]]||0),x=center+(j-1)*bw*1.12-bw/2,yy=y(val),barY=val>=0?yy:zero,barH=Math.max(1,Math.abs(zero-yy));ctx.fillStyle=d[2];ctx.fillRect(x,barY,bw,barH);hits.push({x,y:barY,w:bw,h:barH,row,index:i,series:d[1]})});ctx.fillStyle=chartPalette.text;ctx.textAlign='center';ctx.textBaseline='top';ctx.fillText(String(row.crop).length>11?String(row.crop).slice(0,10)+'…':row.crop,center,h-bottom+12)});
 let lx=left;ctx.font='10px Arial';defs.forEach(d=>{ctx.fillStyle=d[2];ctx.fillRect(lx,h-14,9,9);ctx.fillStyle=chartPalette.text;ctx.textAlign='left';ctx.fillText(d[1],lx+13,h-13);lx+=d[1].length*6+34});
 const hitAt=e=>{const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y0=e.clientY-r.top;return {x,y:y0,bar:hits.find(b=>x>=b.x-4&&x<=b.x+b.w+4&&y0>=b.y-4&&y0<=b.y+b.h+4),idx:Math.max(0,Math.min(rows.length-1,Math.floor((x-left)/group)))}};
 canvas.onmousemove=e=>{const a=hitAt(e);if(a.bar){const r=a.bar.row;chartTooltip('cropPerformanceTooltip',canvas,a.x,a.y,`<b>${esc(r.crop)} · ${a.bar.series}</b><br>Revenue: ${inr(r.revenue_inr)}<br>Expenses: ${inr(r.expenses_inr)}<br>Net profit: ${inr(r.profit_inr)}`)}else hideChartTooltip('cropPerformanceTooltip')};
 canvas.onmouseleave=()=>hideChartTooltip('cropPerformanceTooltip');canvas.onclick=e=>{const a=hitAt(e);if(a.x<left||a.x>w-right)return;$('aCropFilter').value=rows[a.idx].crop;loadAnalytics()};
}
function renderQuantityBars(id,items,labelKey,valueKey,unit){const root=$(id);const valid=items.filter(x=>x[valueKey]!=null);if(!valid.length){root.innerHTML='<p class="empty-note">No recorded values available.</p>';return}const max=Math.max(1,...valid.map(x=>Math.abs(Number(x[valueKey]||0))));root.innerHTML=valid.map(x=>`<div class="bar-row"><span>${esc(x[labelKey])}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.max(0,Math.abs(Number(x[valueKey]||0))/max*100)}%"></div></div><span class="bar-value">${Number(x[valueKey]).toLocaleString('en-IN',{maximumFractionDigits:2})} ${esc(unit)}</span></div>`).join('')}
function renderExpenseBreakdown(items){const root=$('expenseBreakdown');if(!items.length){root.innerHTML='<p class="empty-note">No expense records yet.</p>';return}const max=Math.max(1,...items.map(x=>Number(x.amount_inr||0)));root.innerHTML=items.map(x=>`<div class="bar-row"><span>${esc(x.category)}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.max(0,Number(x.amount_inr||0)/max*100)}%"></div></div><span class="bar-value">${inr(x.amount_inr)} · ${x.percentage}%</span></div>`).join('')}
function renderExpenseDonut(items){
 const c=$('expenseDonut');if(!c)return;const valid=(items||[]).filter(x=>Number(x.amount_inr||0)>0),total=valid.reduce((a,x)=>a+Number(x.amount_inr||0),0);
 const {ctx,w,h}=chartCanvasSize(c,240);const cx=w/2,cy=112,outer=Math.min(78,w*.22),inner=outer*.58,palette=['#39875b','#d7a34a','#6e9eaf','#b87955','#7e78a6','#86a96b','#bd8d9a','#648d82','#a3a35c','#9c775e','#7292a3','#8e8e8e'];
 if(!total){ctx.fillStyle=chartPalette.text;ctx.font='13px Arial';ctx.textAlign='center';ctx.fillText('No expense records',cx,cy);hideChartTooltip('expenseTooltip');c.onmousemove=null;c.onclick=null;return}
 let angle=-Math.PI/2;const slices=[];valid.forEach((x,i)=>{const start=angle,next=angle+Number(x.amount_inr)/total*Math.PI*2;ctx.beginPath();ctx.arc(cx,cy,outer,start,next);ctx.arc(cx,cy,inner,next,start,true);ctx.closePath();ctx.fillStyle=palette[i%palette.length];ctx.fill();slices.push({start,end:next,item:x,color:palette[i%palette.length]});angle=next});
 ctx.fillStyle='#294b37';ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='bold 12px Arial';ctx.fillText(inr(total),cx,cy-4);ctx.font='10px Arial';ctx.fillStyle=chartPalette.text;ctx.fillText('Total expenses',cx,cy+13);
 const locate=e=>{const r=c.getBoundingClientRect(),x=e.clientX-r.left-cx,y=e.clientY-r.top-cy,dist=Math.hypot(x,y);if(dist<inner||dist>outer)return null;let a=Math.atan2(y,x);if(a< -Math.PI/2)a+=Math.PI*2;return slices.find(s=>a>=s.start&&a<=s.end)||null};
 c.onmousemove=e=>{const s=locate(e);if(!s){hideChartTooltip('expenseTooltip');return}const r=c.getBoundingClientRect();chartTooltip('expenseTooltip',c,e.clientX-r.left,e.clientY-r.top,`<b>${esc(s.item.category)}</b><br>${inr(s.item.amount_inr)}<br>${Number(s.item.percentage||0).toFixed(1)}% of expenses`)};
 c.onmouseleave=()=>hideChartTooltip('expenseTooltip');c.onclick=e=>{const s=locate(e);if(!s)return;const rows=$('expenseBreakdown')?.querySelectorAll('.bar-row')||[];rows.forEach(row=>row.classList.remove('chart-selected'));const match=[...rows].find(row=>row.textContent.includes(s.item.category));if(match){match.classList.add('chart-selected');match.scrollIntoView({behavior:'smooth',block:'nearest'})}};
}

function applyAnalyticsPeriod(period){
 const now=new Date(),end=new Date(now.getFullYear(),now.getMonth()+1,0),start=new Date(now);
 if(period==='year'){start.setMonth(0,1)}
 else if(period==='six'){start.setMonth(now.getMonth()-5,1)}
 else if(period==='quarter'){const q=Math.floor(now.getMonth()/3);start.setMonth(q*3-3,1);end.setTime(new Date(now.getFullYear(),q*3,0).getTime())}
 else {if($('aStart'))$('aStart').value='';if($('aEnd'))$('aEnd').value='';if($('aMonth'))$('aMonth').value='';loadAnalytics();return}
 const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
 $('aStart').value=iso(start);$('aEnd').value=iso(end);if($('aMonth'))$('aMonth').value='';loadAnalytics();
}
function exportAnalyticsReport(){
 const section=$('analytics');if(!section)return;
 document.body.classList.add('printing-analytics');window.print();setTimeout(()=>document.body.classList.remove('printing-analytics'),500);
}

let editingTransactionId=null;
async function loadAnalytics(){
 if(!validDateRange('aStart','aEnd')){$('txMessage').textContent='The From date must be on or before the To date.';return}
 if(!localStorage.getItem('agriCareToken')){$('txMessage').textContent='Sign in or create an account to load your private farm analytics. The separate sample charts above are illustrative only.';return}
 try{const d=await api('/api/analytics/overview'+(queryFilters()?'?'+queryFilters():''));
  $('aRevenue').textContent=inr(d.total_revenue_inr);$('aExpenses').textContent=inr(d.total_expenses_inr);$('aProfit').textContent=inr(d.net_profit_inr);$('aProfit').classList.toggle('green',d.net_profit_inr>=0);if($('aCropCount'))$('aCropCount').textContent=Number(d.total_number_of_crops??(d.crop_performance||[]).length).toLocaleString('en-IN');
  const period=d.selected_period||{};if($('selectedPeriod'))$('selectedPeriod').textContent=`Selected period: ${period.start_date||'All dates'} to ${period.end_date||'All dates'}`;
  if($('aAverageRevenue'))$('aAverageRevenue').textContent=inr(d.average_monthly_revenue_inr);if($('aAverageExpenses'))$('aAverageExpenses').textContent=inr(d.average_monthly_expenses_inr);
  renderMonthlyChart(d.monthly_trends);renderCropPerformanceChart(d.crop_performance);renderExpenseBreakdown(d.expense_breakdown||[]);renderExpenseDonut(d.expense_breakdown||[]);renderBarList('expenseSeasonBars',d.season_expenses||[],'season','amount_inr');$('monthlyProfitRows').innerHTML=d.monthly_trends.length?d.monthly_trends.map(m=>`<tr><td>${esc(m.month)}</td><td>${inr(m.revenue_inr)}</td><td>${inr(m.expenses_inr)}</td><td class="${m.profit_inr>=0?'type-revenue':'type-expense'}">${inr(m.profit_inr)}</td></tr>`).join(''):'<tr><td colspan="4" class="empty-note">No monthly financial records yet.</td></tr>';if(d.highest_expense_category)$('expenseBreakdown').insertAdjacentHTML('afterbegin',`<p class="muted">Highest category: <b>${esc(d.highest_expense_category.category)}</b> (${d.highest_expense_category.percentage}% of recorded expenses)</p>`);
  $('txRows').innerHTML=d.records.length?d.records.slice(0,100).map(r=>`<tr><td>${esc(r.transaction_date)}</td><td class="type-${esc(r.transaction_type)}">${r.transaction_type==='revenue'?'Revenue':'Expense'}</td><td>${esc(r.crop)}</td><td>${esc(r.category||'—')}</td><td>${inr(r.amount_inr)}</td><td>${esc([r.district,r.state].filter(Boolean).join(', ')||'—')}</td><td><button class="tiny" onclick="editTransaction(${r.id})">Edit</button> <button class="tiny danger" onclick="deleteTransaction(${r.id})">Delete</button></td></tr>`).join(''):'<tr><td colspan="7" class="empty-note">No farm records match these filters. Add your actual records above.</td></tr>';
  await loadCrops();
 }catch(e){$('txMessage').textContent='Could not load analytics: '+e.message}
}
async function saveFarmRecord(){const amount=Number($('txAmount').value),crop=$('txCrop').value.trim(),date=$('txDate').value;if(!crop||!date||!Number.isFinite(amount)||amount<0){show('txMessage','Enter a crop, valid amount in INR, and transaction date.');return}
 const body={transaction_type:$('txType').value,crop,category:$('txCategory').value,amount_inr:amount,quantity_quintals:$('txQuantity').value?Number($('txQuantity').value):null,season:$('txSeason').value,state:$('txState').value,district:$('txDistrict').value,transaction_date:date,notes:$('txNotes').value};
 try{await api(editingTransactionId?`/api/analytics/transactions/${editingTransactionId}`:'/api/analytics/transactions',{method:editingTransactionId?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});editingTransactionId=null;show('txMessage','Farm record saved. Analytics have been refreshed.');$('txAmount').value='';$('txQuantity').value='';$('txNotes').value='';await loadAnalytics();}catch(e){show('txMessage','Unable to save record: '+e.message)}}
async function editTransaction(id){try{const d=await api('/api/analytics/transactions');const r=d.records.find(x=>x.id===id);if(!r)return;editingTransactionId=id;$('txType').value=r.transaction_type;$('txCrop').value=r.crop;$('txCategory').value=r.category;$('txAmount').value=r.amount_inr;$('txQuantity').value=r.quantity_quintals||'';$('txSeason').value=r.season||'';$('txState').value=r.state||'';$('txDistrict').value=r.district||'';$('txDate').value=r.transaction_date;$('txNotes').value=r.notes||'';$('txMessage').textContent='Editing record #'+id+'. Save to apply changes.';}catch(e){$('txMessage').textContent=e.message}}
async function deleteTransaction(id){if(!confirm('Delete this farm transaction?'))return;try{await api('/api/analytics/transactions/'+id,{method:'DELETE'});await loadAnalytics();}catch(e){$('txMessage').textContent=e.message}}
async function authAction(action){const name=$('authName').value.trim(),email=$('authEmail').value.trim(),password=$('authPassword').value;if(!email||!password||(action==='register'&&!name)){$('authMessage').textContent=action==='register'?'Enter your name, email and password.':'Enter your email and password.';return}try{const payload=action==='register'?{name,email,password}:{email,password};const d=await api('/api/auth/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});localStorage.setItem('agriCareToken',d.access_token);$('authMessage').textContent=action==='register'?'Account created and signed in.':'Signed in successfully.';await loadAnalytics();}catch(e){$('authMessage').textContent=e.message}}
function logoutFarmer(){localStorage.removeItem('agriCareToken');editingTransactionId=null;editingCropId=null;$('authMessage').textContent='Signed out. Private analytics are locked.';$('txRows').innerHTML='<tr><td colspan="7" class="empty-note">Sign in to view your records.</td></tr>';$('cropRows').innerHTML='<tr><td colspan="16" class="empty-note">Sign in to view your crop records.</td></tr>';$('aRevenue').textContent='₹0';$('aExpenses').textContent='₹0';$('aProfit').textContent='₹0';$('aAverageRevenue').textContent='₹0';$('aAverageExpenses').textContent='₹0';if($('aCropCount'))$('aCropCount').textContent='0';$('monthlyProfitRows').innerHTML='<tr><td colspan="4" class="empty-note">Sign in to view your records.</td></tr>';$('txMessage').textContent='';$('cropMessage').textContent='';$('expenseBreakdown').innerHTML='<p class="empty-note">Sign in to view your records.</p>';['cropChart','cropExpenseBars','expenseSeasonBars','cropRevenueBars','cropProfitBars','cropProductionBars','cropYieldBars','seasonalPerformanceBars'].forEach(id=>{if($(id))$(id).innerHTML='<p class="empty-note">Sign in to view your records.</p>'});renderMonthlyChart([]);renderExpenseDonut([]);resetCropForm();}
let editingCropId=null;
function resetCropForm(){editingCropId=null;['cropRecordId','crCrop','crArea','crSowing','crHarvest','crProduction','crPrice','crPriceSource','crState','crDistrict','crSoil','crNotes'].forEach(id=>$(id).value='');$('crSeason').value='Kharif';$('crVerified').checked=false;}
async function loadCrops(){if(!localStorage.getItem('agriCareToken'))return;try{const d=await api('/api/analytics/crops'+(queryFilters()?'?'+queryFilters():''));const rows=d.records||[];$('cropRows').innerHTML=rows.length?rows.map(r=>`<tr><td>${esc(r.crop)}</td><td>${r.area_acres} ac</td><td>${esc(r.season)}</td><td>${esc(r.sowing_date||'—')}</td><td>${esc(r.harvest_date||'—')}</td><td>${r.production_kg==null?'—':Number(r.production_kg).toLocaleString('en-IN')+' kg'}</td><td>${r.yield_kg_per_acre==null?'—':Number(r.yield_kg_per_acre).toLocaleString('en-IN')+' kg'}</td><td>${r.selling_price_inr_per_quintal==null?'—':inr(r.selling_price_inr_per_quintal)}</td><td>${esc([r.district,r.state].filter(Boolean).join(', ')||'—')}</td><td>${esc(r.revenue_status)}</td><td>${r.revenue_inr==null?'—':inr(r.revenue_inr)}</td><td>${r.estimated_revenue_inr==null?'—':inr(r.estimated_revenue_inr)}</td><td>${inr(r.expenses_inr)}</td><td>${r.profit_inr==null?'—':inr(r.profit_inr)}</td><td>${esc(r.performance_status)}</td><td><button class="tiny" onclick="editCropRecord(${r.id})">Edit</button> <button class="tiny danger" onclick="deleteCropRecord(${r.id})">Delete</button></td></tr>`).join(''):'<tr><td colspan="16" class="empty-note">No crop records yet.</td></tr>';renderBarList('cropRevenueBars',rows.filter(r=>r.revenue_inr!=null),'crop','revenue_inr');renderBarList('cropProfitBars',rows.filter(r=>r.profit_inr!=null),'crop','profit_inr');renderQuantityBars('cropProductionBars',rows,'crop','production_kg','kg');renderQuantityBars('cropYieldBars',rows,'crop','yield_kg_per_acre','kg/acre');const seasons={};rows.forEach(r=>{seasons[r.season]??={profit:0,count:0};if(r.profit_inr!=null){seasons[r.season].profit+=r.profit_inr;seasons[r.season].count++}});renderQuantityBars('seasonalPerformanceBars',Object.entries(seasons).filter(([,v])=>v.count).map(([season,v])=>({season,value:v.profit})),'season','value','₹ profit');}catch(e){$('cropMessage').textContent=e.message}}
async function saveCropRecord(){const body={crop:$('crCrop').value.trim(),area_acres:Number($('crArea').value),season:$('crSeason').value,sowing_date:$('crSowing').value||null,harvest_date:$('crHarvest').value||null,production_kg:$('crProduction').value?Number($('crProduction').value):null,selling_price_inr_per_quintal:$('crPrice').value?Number($('crPrice').value):null,price_verified:$('crVerified').checked,price_source:$('crPriceSource').value,state:$('crState').value,district:$('crDistrict').value,soil_type:$('crSoil').value,notes:$('crNotes').value};if(!body.crop||!body.area_acres){$('cropMessage').textContent='Enter a crop name and cultivated area.';return}try{await api(editingCropId?`/api/analytics/crops/${editingCropId}`:'/api/analytics/crops',{method:editingCropId?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});resetCropForm();$('cropMessage').textContent='Crop record saved.';await loadCrops();}catch(e){$('cropMessage').textContent=e.message}}
async function editCropRecord(id){try{const d=await api('/api/analytics/crops');const r=d.records.find(x=>x.id===id);if(!r)return;editingCropId=id;$('crCrop').value=r.crop;$('crArea').value=r.area_acres;$('crSeason').value=r.season;$('crSowing').value=r.sowing_date||'';$('crHarvest').value=r.harvest_date||'';$('crProduction').value=r.production_kg??'';$('crPrice').value=r.selling_price_inr_per_quintal??'';$('crVerified').checked=!!r.price_verified;$('crPriceSource').value=r.price_source||'';$('crState').value=r.state||'';$('crDistrict').value=r.district||'';$('crSoil').value=r.soil_type||'';$('crNotes').value=r.notes||'';$('cropMessage').textContent='Editing crop record #'+id;}catch(e){$('cropMessage').textContent=e.message}}
async function deleteCropRecord(id){if(!confirm('Delete this crop record?'))return;try{await api('/api/analytics/crops/'+id,{method:'DELETE'});await loadCrops()}catch(e){$('cropMessage').textContent=e.message}}
function weatherCodeLabel(code){const m={0:'Clear sky',1:'Mainly clear',2:'Partly cloudy',3:'Overcast',45:'Fog',48:'Depositing rime fog',51:'Light drizzle',53:'Drizzle',55:'Dense drizzle',61:'Slight rain',63:'Moderate rain',65:'Heavy rain',71:'Slight snow',73:'Moderate snow',75:'Heavy snow',80:'Rain showers',81:'Moderate rain showers',82:'Violent rain showers',95:'Thunderstorm',96:'Thunderstorm with hail',99:'Thunderstorm with heavy hail'};return m[code]||'Weather code '+code}
async function loadWeather(){
  const lat=Number($('weatherLat').value),lon=Number($('weatherLon').value);
  if(!Number.isFinite(lat)||!Number.isFinite(lon)||lat < -90||lat>90||lon < -180||lon>180){$('weatherResult').innerHTML='<p class="empty-note">Enter valid latitude and longitude coordinates.</p>';return}
  $('weatherResult').innerHTML='<p class="empty-note">Loading live weather…</p>';
  try{const d=await api(`/api/weather/current?latitude=${encodeURIComponent(lat)}&longitude=${encodeURIComponent(lon)}`),c=d.current;
    $('weatherResult').innerHTML=`<p><b>${esc(weatherCodeLabel(c.weather_code))}</b> · Updated ${esc(d.updated_at||'time unavailable')} · Source: ${esc(d.source)}</p>
    <div class="weather-current"><div class="weather-metric"><small>Temperature</small><strong>${c.temperature_c??'—'} °C</strong></div><div class="weather-metric"><small>Humidity</small><strong>${c.humidity_percent??'—'}%</strong></div><div class="weather-metric"><small>Precipitation</small><strong>${c.precipitation_mm??'—'} mm</strong></div><div class="weather-metric"><small>Wind</small><strong>${c.wind_speed_kmh??'—'} km/h</strong></div></div>
    <b>5-day forecast</b><div class="forecast-list">${d.forecast.map(f=>`<div class="forecast-day">${esc(f.date||'—')}<b>${f.max_temp_c??'—'}° / ${f.min_temp_c??'—'}°</b><span>Rain ${f.rain_probability_percent??'—'}%</span><br><span>${f.precipitation_mm??'—'} mm</span></div>`).join('')}</div>
    <div class="notice"><b>Weather advisory</b><ul>${d.advisory.rules_based_advisory.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>${esc(d.advisory.disclaimer)}</div>`;
  }catch(e){$('weatherResult').innerHTML=`<p class="empty-note">Live weather could not be loaded: ${esc(e.message)}. Check the coordinates and try again.</p>`}
}

let historicalMarketPage=1;
function setRecentMarketDateRange(){const end=new Date();const start=new Date(end);start.setDate(end.getDate()-29);const localISO=d=>{const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`};if($('hmStart'))$('hmStart').value=localISO(start);if($('hmEnd'))$('hmEnd').value=localISO(end);}
function resetMarketFilters(){if($('hmCommodity'))$('hmCommodity').value='';['hmState','hmDistrict','hmMarket','hmSearch'].forEach(id=>{if($(id))$(id).value=''});setRecentMarketDateRange();$('hmGranularity').value='daily';$('hmPageSize').value='50';historicalMarketPage=1;loadHistoricalMarket();}
function marketParams(){const p=new URLSearchParams();[['commodity','hmCommodity'],['state','hmState'],['district','hmDistrict'],['market','hmMarket'],['start_date','hmStart'],['end_date','hmEnd'],['granularity','hmGranularity'],['search','hmSearch']].forEach(([k,id])=>{const v=$(id)?.value?.trim();if(v)p.set(k,v)});return p}
function renderMarketTrend(items){const c=$('hmTrend'),empty=$('hmTrendEmpty');if(!items?.length){c.style.display='none';empty.style.display='block';return}c.style.display='block';empty.style.display='none';const ctx=c.getContext('2d'),w=c.clientWidth||600,h=230,dpr=window.devicePixelRatio||1;c.width=w*dpr;c.height=h*dpr;ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);const vals=items.map(x=>Number(x.avg_modal||0)),max=Math.max(1,...vals),min=Math.min(...vals);const pad=30;ctx.strokeStyle='#e6eee8';for(let i=0;i<4;i++){const y=pad+(h-pad*2)*i/3;ctx.beginPath();ctx.moveTo(pad,y);ctx.lineTo(w-12,y);ctx.stroke()}ctx.beginPath();items.forEach((x,i)=>{const px=pad+(w-pad-18)*(i/Math.max(1,items.length-1)),py=h-pad-(Number(x.avg_modal||0)-min)/(max-min||1)*(h-pad*2);i?ctx.lineTo(px,py):ctx.moveTo(px,py)});ctx.strokeStyle='#39875b';ctx.lineWidth=2.5;ctx.stroke();ctx.fillStyle='#61766a';ctx.font='10px Arial';items.forEach((x,i)=>{if(i%Math.ceil(items.length/8)===0||i===items.length-1){const px=pad+(w-pad-18)*(i/Math.max(1,items.length-1));ctx.fillText(x.period.slice(5),px-10,h-8)}});c.title='Click a month to narrow the historical price date range';c.onclick=e=>{const rect=c.getBoundingClientRect(),x=e.clientX-rect.left,idx=Math.round((x-pad)/(w-pad-18)*(items.length-1));if(idx>=0&&idx<items.length){const [yy,mm]=items[idx].period.split('-').map(Number),last=new Date(yy,mm,0).getDate();$('hmStart').value=`${yy}-${String(mm).padStart(2,'0')}-01`;$('hmEnd').value=`${yy}-${String(mm).padStart(2,'0')}-${last}`;historicalMarketPage=1;loadHistoricalMarket();}}}
async function loadHistoricalFilters(){try{const d=await api('/api/market/historical/filters?granularity='+encodeURIComponent($('hmGranularity').value));const sel=$('hmCommodity'),chosen=sel.value,all=[...new Set(['Tomato','Rice','Cotton','Onion','Maize','Wheat','Groundnut','Chilli','Turmeric','Potato','Banana','Mango','Soybean','Mustard','Chickpea','Tur',...(d.commodities||[])])].sort();sel.innerHTML='<option value="">All available commodities</option>'+all.map(x=>`<option>${esc(x)}</option>`).join('');sel.value=chosen;[['hmState',d.states],['hmDistrict',d.districts],['hmMarket',d.markets]].forEach(([id,values])=>{const listId=id+'List';let dl=$(listId);if(!dl){dl=document.createElement('datalist');dl.id=listId;document.body.appendChild(dl);$(id).setAttribute('list',listId)}dl.innerHTML=(values||[]).map(x=>`<option value="${esc(x)}"></option>`).join('')});}catch(e){/* Empty data store: keep user-entered filters available. */}}

function renderMarketSnapshot(data){
 const records=data.records||[],watch=$('hmWatchlist'),title=$('hmInsightTitle'),copy=$('hmInsightText'),meta=$('hmInsightMeta');
 if(!records.length){title.textContent='Market data unavailable';copy.textContent='No source-attributed mandi observations match these filters. Import an official dataset or adjust the crop, location and date filters to view market information.';meta.textContent='No prices have been generated or estimated.';watch.innerHTML='<p class="empty-note">No matching market observations are available. Change filters or import a verified source file.</p>';return;}
 const latest=[...records].sort((a,b)=>String(b.report_date||'').localeCompare(String(a.report_date||'')))[0];
 const priced=records.filter(r=>r.modal_price!=null&&Number.isFinite(Number(r.modal_price)));
 const highest=priced.length?[...priced].sort((a,b)=>Number(b.modal_price)-Number(a.modal_price))[0]:null;
 title.textContent=latest.commodity+' · '+(latest.market||latest.district||latest.state||'Market observation');
 copy.textContent=`Latest matching observation: ${latest.report_date||'date unavailable'} at ${latest.market||'market not specified'}, ${[latest.district,latest.state].filter(Boolean).join(', ')||'location not specified'}. Modal price: ${latest.modal_price==null?'not reported':inr(latest.modal_price)+' per quintal'}.`;
 meta.textContent=`Source: ${latest.source||'not specified'} · ${data.granularity||'historical'} records`;
 const shown=records.slice(0,5);watch.innerHTML=shown.map(r=>`<div class="market-watch-item"><span class="market-watch-symbol">${esc((r.commodity||'?').slice(0,1).toUpperCase())}</span><div class="market-watch-main"><b>${esc(r.commodity||'Commodity')}</b><small>${esc(r.market||r.district||r.state||'Market not specified')} · ${esc(r.report_date||'Date unavailable')}</small></div><strong>${r.modal_price==null?'—':inr(r.modal_price)}</strong></div>`).join('');
 if(highest&&Number(highest.modal_price)>0){copy.textContent+=` Highest modal price among the displayed page records: ${highest.commodity} at ${highest.market||'market not specified'} (${inr(highest.modal_price)} per quintal). This is an observed comparison, not a price forecast.`;}
}
